import sys

def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    exp = int(data)
    if exp < 5:
        print("Junior")
        print("Salary: 30000")
    elif exp <= 10:
        print("Mid-level")
        print("Salary: 50000")
    else:
        print("Senior")
        print("Salary: 70000")

if __name__ == "__main__":
    solve()
